### FUNCION: conectar
```js
function conectar() {
  const container = document.getElementById('spreadsheet-container');

  /** 
   * Usamos event delegation en el contenedor para capturar eventos de entrada (typing) 
   */
  container.addEventListener('input', (event) => {
    const target = event.target;

    // Verificar que el objetivo del evento sea una celda de datos y tenga su atributo data-cell.
    if (!target || !target.hasAttribute('data-cell')) return;

    const address = target.getAttribute('data-cell');
    // El nuevo valor es el contenido actual del elemento DOM después del evento 'input'.
    const newValue = target.textContent; 

    // 1. Lógica: Actualizar el estado interno con el nuevo valor.
    updateCellValue(address, newValue); 

    // 2. Persistencia: Guardar el nuevo estado en LocalStorage.
    guardar();

    // 3. Dibujo: Re-renderizar toda la hoja para asegurar que cualquier cambio de formato o cálculo se aplique (aunque aquí solo es texto).
    render();
  });

  /** Context menu handler for formatting */
  container.addEventListener('contextmenu', (event) => {
    // Prevenir el menú contextual por defecto del navegador
    event.preventDefault(); 
    const target = event.target;

    if (!target || !target.hasAttribute('data-cell')) return;

    const address = target.getAttribute('data-cell');
    let menuHtml = `
        <div class="context-menu" style="position: absolute; top: ${event.pageY}px; left: ${event.pageX}px;">
            <div class="context-menu-item color-picker">Color de Fondo</div>
        </div>`;

    // Crear y mostrar el menú en un elemento temporal para evitar problemas de posicionamiento
    const tempMenu = document.createElement('div');
    tempMenu.innerHTML = menuHtml;
    document.body.appendChild(tempMenu);
    const menuElement = tempMenu.querySelector('.context-menu');

    // Llenar el menú con opciones de color (ejemplo: rojo, azul, verde)
    ['#FF0000', '#0000FF', '#008000'].forEach(color => {
        const item = document.createElement('div');
        item.className = 'context-menu-item';
        item.style.backgroundColor = color;
        item.dataset.color = color;
        item.textContent = ''; // Ocultar texto para solo ver el color
        menuElement.appendChild(item);
    });

    // Manejar el clic dentro del menú
    const handleMenuClick = (e) => {
      const clickedItem = e.target.closest('.context-menu-item');
      if (clickedItem && clickedItem.dataset.color) {
        const color = clickedItem.dataset.color;
        // Lógica: Aplicar el fondo y refrescar
        applyBackgroundColor(address, color);
        render(); // Re-renderizar para que se refleje visualmente
      }
      // Ocultar el menú tras seleccionar algo
      menuElement.removeEventListener('click', handleMenuClick); 
      document.body.removeChild(tempMenu);
    };

    // Asignar el listener y mostrar el menú
    const showMenu = (e) => {
        if (e.target === menuElement) {
            handleMenuClick(e);
        }
    };
    menuElement.addEventListener('click', handleMenuClick);
    document.addEventListener('click', showMenu);

  });
}
