function cargar() { 
    try { 
        const s = localStorage.getItem(CLAVE); 
        if (s) {
            estado = JSON.parse(s); 
            console.log("Datos cargados desde LocalStorage.");
        } else {
            // Inicializar un estado limpio si no hay datos guardados, incluyendo formatos por defecto.
            const initialCells = {};
            // Generar estructura inicial para todas las celdas posibles (A1:J20) con formato base.
            for (let i = 1; i <= 20; i++) {
                for (let j = 0; j < 10; j++) { // Column A to J
                    const address = String.fromCharCode(65 + j) + i;
                    initialCells[address] = { value: '', format: {} };
                }
            }
            estado = { cells: initialCells };
        }
    } catch (e) {
        console.error("Error al cargar el estado:", e);
    } 
}
