function deleteColumn(columnIndex) {
    if (!estado.selectedColumn || !estado.selectedColumn[0].toUpperCase() === columnIndex.toUpperCase()) {
        alert("Debe seleccionar la columna a eliminar primero.");
        return;
    }

    if (!confirm(`¿Está seguro de que desea eliminar la Columna ${columnIndex}? Esta acción es irreversible.`)) {
        return;
    }

    // 1. Identificar todas las direcciones (A1, B2, etc.) en esta columna.
    const addressesToDelete = [];
    let rowCount = 0;
    // Asumimos que hay hasta 20 filas de contenido + la fila 0 del encabezado.
    while (rowCount < 21) { // Iterate up to row index 20 (or max rows supported)
        const address = `${columnIndex}${rowCount}`;
        if (estado.cells[address] !== undefined) {
            addressesToDelete.push(address);
        }
        rowCount++;
    }

    // 2. Eliminar los datos del estado para esa columna.
    for (const address of addressesToDelete) {
        delete estado.cells[address];
    }

    // 3. Reconstruir el DOM y mapear las direcciones de todas las celdas posteriores.
    // Esto es complejo, así que simplificamos: limpiamos la columna en el HTML.

    const headers = document.getElementById('col-headers').querySelectorAll('.col-header');
    let colIndexToRemove = -1;
    for (let i = 0; i < headers.length; i++) {
        if (headers[i].dataset.columnLetter === columnIndex) {
            colIndexToRemove = i + 1; // Ajustar para contar desde el índice real de la tabla
            break;
        }
    }

    // Eliminar el encabezado de columna
    if (colIndexToRemove > 0 && colIndexToRemove <= headers.length) {
         headers[colIndexToRemove - 1].remove();
    }


    const tbody = document.querySelector('#spreadsheet-container tbody');
    let rows = tbody.querySelectorAll('tr');

    for (let i = 0; i < rows.length; i++) {
        const row = rows[i];
        // Iterar sobre las celdas de la fila actual
        const cells = Array.from(row.querySelectorAll('td'));

        // Encontrar el TD que corresponde a la columna a borrar (es el índice 'colIndexToRemove - 1' en los TDs)
        if (cells.length > colIndexToRemove - 1) {
            cells[colIndexToRemove - 1].remove();
        }
    }

    // 4. Limpiar estado y re-renderizar.
    estado.selectedColumn = null;
    guardar();
    render();
}
