### FUNCION: deleteColumn
```js
function deleteColumn() {
    const currentColLetter = estado.selectedColumn;
    if (!currentColLetter) return;

    // 1. Recolección y remapeo de datos (Lógica compleja):
    let newCells = {};
    let columnOrder = []; // Para saber qué columnas quedan

    // Obtener todas las letras de columna existentes para determinar el nuevo mapeo.
    const allHeaders = Array.from(document.querySelectorAll('#column-headers .col-header')).map(th => th.getAttribute('data-column-letter'));
    let newColIndex = 0;
    let mapping = {}; // Mapa de letras antiguas a letras nuevas

    // Generar el mapa de remapeo para las columnas que NO se eliminan.
    for (let i = 1; i < allHeaders.length; i++) {
        const letter = allHeaders[i];
        if (letter !== currentColLetter) {
            mapping[letter] = String.fromCharCode(65 + newColIndex); // A=65, B=66...
            newColIndex++;
        }
    }

    // Crear el nuevo estado de celdas mapeando las direcciones antiguas a las nuevas.
    for (const address in estado.cells) {
        const oldAddress = address;
        const rowMatch = oldAddress.match(/([A-Z]+)([1-9][0-9]*)/i); // Captura Columna y Fila
        if (!rowMatch) continue;

        let oldColLetter = rowMatch[1].toUpperCase();
        let rowNum = parseInt(rowMatch[2]);

        let newColLetter = mapping[oldColLetter] || oldColLetter; // Si la columna no se mapea (ej: ya está fuera de rango), mantenerla.

        // Esto es una simplificación extrema, asumiendo que el remapeo debe ser perfecto. 
        // Solo actualizamos si la columna original era la seleccionada o si necesitamos un nuevo nombre.
        if (oldColLetter === currentColLetter) {
            continue; // Ignorar datos de la columna a borrar
        }

        let newAddress = `${newColLetter}${rowNum}`;
        newCells[newAddress] = estado.cells[oldAddress];
    }

    // 2. Actualizar el estado interno:
    estado.cells = newCells;

    // 3. Limpieza del DOM (Visual):
    const tableBody = document.querySelector('#spreadsheet-container tbody');
    if (!tableBody) return;

    // Encontrar la columna a eliminar y removerla de todas las filas (tr).
    let columnIndexToDelete = -1;
    let headerElements = Array.from(document.querySelectorAll('#column-headers .col-header'));

    headerElements.forEach((th, index) => {
        if (th.getAttribute('data-column-letter') === currentColLetter) {
            columnIndexToDelete = index + 1; // Índice en el tbody comienza después del th vacío inicial.
        }
    });


    // Iterar sobre todas las filas y eliminar la celda correspondiente.
    document.querySelectorAll('#spreadsheet-container table tbody tr').forEach(row => {
        if (columnIndexToDelete >= 0) {
            let cellToRemove = row.children[columnIndexToDelete];
            if (cellToRemove) {
                // Si es necesario, se podría limpiar el contenido antes de removerlo para evitar errores JS.
                cellToRemove.remove();
            }
        }
    });

