let estado = { cells: {}, selectedColumn: null }; // Añadimos selectedColumn para rastrear qué columna está activa
const CLAVE = "app";

function cargar() { 
    try { 
        const s = localStorage.getItem(CLAVE); 
        if (s) {
            estado = JSON.parse(s); 
            console.log("Datos cargados desde LocalStorage.");
        } else {
            // Inicializar un estado limpio si no hay datos guardados
            estado = { cells: {}, selectedColumn: null };
        }
    } catch (e) {
        console.error("Error al cargar el estado:", e);
    } 
}

function guardar() { 
    try { 
        localStorage.setItem(CLAVE, JSON.stringify(estado)); 
        console.log("Estado guardado.");
    } catch (e) {
        console.error("Error al guardar el estado:", e);
    } 
}

