/* Estilos para la hoja de cálculo */
body {
    font-family: Arial, sans-serif;
}

#spreadsheet-container {
    overflow-x: auto;
    border: 1px solid #ccc;
    display: inline-block; /* Para que solo ocupe el ancho necesario */
}

/* Estilo para la tabla en general */
table {
    border-collapse: collapse;
    width: fit-content;
}

th, td {
    border: 1px solid #ccc;
    padding: 5px;
    min-width: 80px; /* Asegura un ancho base razonable */
    text-align: left;
    cursor: pointer;
    transition: background-color 0.2s;
}

/* Encabezados de Columna (A, B, C...) */
.col-header {
    background-color: #f4f4f4;
    font-weight: bold;
    cursor: pointer;
    text-align: center;
}

/* Estilo cuando una columna está seleccionada */
.selected-column {
    background-color: #d0eaff !important; /* Azul claro de selección */
    box-shadow: inset 0 0 5px rgba(0, 0, 0, 0.2);
}

/* Estilo para la celda activa (donde se escribe) */
[contenteditable="true"]:focus {
    background-color: #fffacd; /* Amarillo claro al enfocar */
    outline: none;
    box-shadow: inset 0 0 3px rgba(0, 0, 0, 0.2);
}

/* Estilos para la esquina superior izquierda (números de fila) */
thead th:first-child {
    background-color: #e9e9e9;
    width: 40px;
    text-align: center;
}

/* Controles Adicionales */
.control-panel {
    margin: 20px 20px 10px 20px;
    padding: 15px;
    border: 1px solid #ddd;
    background-color: #f9f9f9;
}

#clear-col-btn {
    padding: 8px 15px;
    background-color: #dc3545; /* Rojo */
    color: white;
    border: none;
    cursor: pointer;
    margin-top: 10px;
}

#clear-col-btn:disabled {
    background-color: #aaa;
    cursor: not-allowed;
}
