function applyColumnFormatting(letter, color = null) {
    // 1. Limpiar cualquier selección previa en los encabezados
    document.querySelectorAll('.col-header').forEach(th => {
        th.classList.remove('selected-column');
    });

    const $headers = document.querySelectorAll('.col-header');
    let selectedHeader = null;
    for (let i = 0; i < $headers.length; i++) {
        if ($headers[i].textContent.trim().toUpperCase() === letter.toUpperCase()) {
            selectedHeader = $headers[i];
            selectedHeader.classList.add('selected-column');
            break;
        }
    }

    // 2. Identificar todos los TDs de esa columna (A1, A2, ..., J20)
    const allRows = document.querySelectorAll('#spreadsheet-container tbody tr');
    let columnCells = [];

    for (const row of allRows) {
        // Iterar sobre las celdas del TR para encontrar la que corresponde a 'letter'
        row.querySelectorAll('td').forEach((td, colIndex) => {
            // Calcular si esta TD pertenece a la columna deseada
            // columnIndex 0 = A, 1 = B, ...
            const expectedLetterCode = 'A'.charCodeAt(0) + colIndex;
            const targetCharCode = letter.toUpperCase().charCodeAt(0);

            if (expectedLetterCode === targetCharCode && td.getAttribute('data-cell')) {
                columnCells.push(td);
            }
        });
    }

    // 3. Aplicar la lógica de coloración o limpieza
    if (!columnCells.length) return;

    if (color !== null) {
        // Cambiar el fondo de todas las celdas en la columna seleccionada
        const style = document.createElement('style');
        style.textContent = `
            /* Este estilo es solo para demostrar el color, pero se aplicará vía JS */
        `;
        document.head.appendChild(style);

        columnCells.forEach(cell => {
            cell.style.backgroundColor = color;
            // Actualizar estado y renderizado si fuera necesario (aunque aquí no cambia contenido)
            const address = cell.getAttribute('data-cell');
            if (address) updateCellValue(address, state.cells[address] || ''); 
        });

    } else if (color === 'clear') {
        // Borrar el contenido de todas las celdas en la columna seleccionada
        columnCells.forEach(cell => {
            const address = cell.getAttribute('data-cell');
            if (address) {
                // 1. Actualizar estado interno a vacío
                updateCellValue(address, '');
                // 2. Limpiar el DOM
                cell.textContent = '';
            }
        });
    }

    // 4. Persistencia y Dibujo final
    guardar();
    render();
}
