function setColumnBackgroundColor(columnLetter, color) {
    // Recorre todas las filas de la tabla para encontrar celdas con esta letra en el encabezado.
    const rows = document.querySelectorAll('#spreadsheet-container tbody tr');

    rows.forEach((row, rowIndex) => {
