```js
function clearColumnContent(columnLetter) {
    const rows = document.querySelectorAll('#spreadsheet-container tbody tr');
    let cellsClearedCount = 0;

    rows.forEach((row, rowIndex) => {
        // Buscar todas las celdas que corresponden a la columna dada.
        const targetCells = row.querySelectorAll(`[data-cell^="${columnLetter}"]`);
        targetCells.forEach(cell => {
            const address = cell.getAttribute('data-cell');
            if (address) {
                // 1. Limpiar el estado interno
                updateCellValue(address, '');
                // 2. Limpiar el contenido visible del DOM
                cell.textContent = '';
                cell.style.backgroundColor = ''; // También limpiamos formato si existía
                cellsClearedCount++;
            }
        });
    });

    if (cellsClearedCount > 0) {
        guardar();
        render();
    }
}
