function handleColumnContextClick(event, letter) {
    // Prevenir el menú contextual por defecto del navegador
    event.preventDefault();

    const menuContainerId = 'column-context-menu';
    let menu = document.getElementById(menuContainerId);

    // 1. Mostrar/Actualizar Menú Contextual (simulado)
    if (!menu) {
        menu = document.createElement('div');
        menu.id = menuContainerId;
        menu.style.position = 'absolute';
        menu.style.zIndex = '1000';
        menu.style.backgroundColor = '#fff';
        menu.style.border = '1px solid #ccc';
        menu.style.boxShadow = '2px 2px 5px rgba(0,0,0,0.2)';
        menu.innerHTML = `
            <div class="menu-item" data-action="color">Cambiar Color de Fondo</div>
            <div class="menu-item" data-action="clear">Borrar Contenido Columna</div>
            <hr style="margin: 5px;">
        `;
        document.body.appendChild(menu);
    } else {
        // Simplemente limpiamos y rellenamos el contenido para la demostración
        menu.innerHTML = `
            <div class="menu-item" data-action="color">Cambiar Color de Fondo</div>
            <div class="menu-item" data-action="clear">Borrar Contenido Columna</div>
            <hr style="margin: 5px;">
        `;
    }

    // Posicionar el menú donde se hizo clic (o cerca)
    const rect = event.currentTarget.getBoundingClientRect();
    menu.style.left = `${rect.left}px`;
    menu.style.top = `${rect.bottom + 5}px`;
    menu.style.display = 'block';

    // 2. Listener para manejar la selección dentro del menú (se añade temporalmente)
    const menuItems = menu.querySelectorAll('.menu-item');
    menuItems.forEach(item => {
        item.onclick = () => {
            const action = item.getAttribute('data-action');
            if (action === 'color') {
                // Para la prueba, simulamos que se abre un color picker y seleccionamos #ff0000
                alert("Simulando selección de Color de Fondo (#ff0000)");
                applyStyleToColumn(letter, '#ff0000');
            } else if (action === 'clear') {
                if (confirm(`¿Desea borrar TODO el contenido y restablecer el fondo de la columna ${letter}?`)) {
                    clearColumn(letter);
                }
            }
            menu.style.display = 'none';
        };
    });

    // 3. Cerrar menú al hacer clic fuera
    document.addEventListener('click', (e) => {
        if (!menu.contains(e.target) && e.target !== event.currentTarget) {
            menu.style.display = 'none';
        }
    });
}
