/**
 * Borra el contenido de todas las celdas en una columna dada, actualizando el estado y re-renderizando la hoja.
 * @param {string} columnLetter - La letra de la columna a limpiar (ej: "A").
 */
function clearColumn(columnLetter) {
    let changed = false;
    for (const address in estado.cells) {
        if (address.toUpperCase().startsWith(columnLetter)) {
            // Solo limpiamos si el contenido no es ya vacío, para evitar llamadas innecesarias (aunque updateCellValue lo maneja).
            if (estado.cells[address] !== '') {
                updateCellValue(address, '');
                changed = true;
            }
        }
    }

    if (changed) {
        guardar();
        render();
    } else {
        console.log(`La columna ${columnLetter} ya estaba vacía.`);
    }
}
