```javascript
/**
 * Maneja las acciones de una columna seleccionada (seleccionar, borrar, limpiar).
 * @param {string} columnLetter - La letra de la columna que se está operando.
 * @param {string} action - La acción a realizar ('select', 'delete', 'clear').
 */
function handleColumnAction(columnLetter, action) {
    // 1. Actualizar el estado o realizar la acción específica basada en la bandera.
    switch (action) {
        case 'select':
            console.log(`Columna ${columnLetter} seleccionada.`);
            // Aquí se debería actualizar un estado de UI que maneje resaltado, pero por ahora solo es informativo.
            break;

        case 'clear':
            // Este bloque soluciona el fallo al asegurar que la limpieza pasa por updateCellValue y render().
            clearColumn(columnLetter);
            return true; // Indica que se procesó una acción válida

        case 'delete':
            if (!confirm(`¿Está seguro de que desea borrar completamente la columna ${columnLetter}? Esta acción no puede deshacerse.`)) {
                return false;
            }

            // Borrar todos los datos asociados a esa columna en el estado.
            for (const address in estado.cells) {
                if (address.toUpperCase().startsWith(columnLetter)) {
                    delete estado.cells[address];
                }
            }
            console.log(`Columna ${columnLetter} borrada de los datos.`);
            guardar();
            render(); // Renderizar después de borrar la columna
            return true;
    }
    return false;
}
