```js
// ===== DATOS: la ÚNICA fuente de verdad. Todo lo que se ve sale de acá. =====
/** 
 * estado.cells es un objeto donde la clave es el ID de la celda (ej: "A1") 
 * y el valor es el contenido actual del texto.
 */
let estado = { cells: {}, selectedRow: null }; // Añadido selectedRow
const CLAVE = "app";

function cargar() { 
    try { 
        const s = localStorage.getItem(CLAVE); 
        if (s) {
            estado = JSON.parse(s); 
            console.log("Datos cargados desde LocalStorage.");
        } else {
            // Inicializar un estado limpio si no hay datos guardados
            estado = { cells: {}, selectedRow: null }; // Inicialización limpia con selectedRow
        }
    } catch (e) {
        console.error("Error al cargar el estado:", e);
    } 
}

function guardar() { 
    try { 
        localStorage.setItem(CLAVE, JSON.stringify(estado)); 
        console.log("Estado guardado.");
    } catch (e) {
        console.error("Error al guardar el estado:", e);
    } 
}

// ===== LÓGICA: funciones que cambian `estado` (o calculan con él). NO tocan la página: sin document. =====

/**
 * Actualiza el contenido de una celda en el estado interno.
 * @param {string} address - La dirección de la celda (ej: "A1").
 * @param {string} value - El nuevo valor del texto.
 */
function updateCellValue(address, value) {
    estado.cells[address] = String(value);
}

/**
 * Intenta evaluar una fórmula de estilo Excel almacenada como string. 
 * Retorna el resultado numérico formateado o la fórmula original si falla.
 * @param {string} formula - La cadena que puede ser un número simple o una fórmula (ej: "=SUMA(A1:A3)").
 * @returns {string} El valor calculado en formato string, o la fórmula original.
 */
function evaluateFormula(formula) {
    if (!formula || !formula.startsWith('=')) return formula;

    let expression = formula.substring(1).trim();
    let calculatedExpression = expression;

    // --- 1. Función SUMA ---
    const sumRegex = /SUMA\(\s*(.*?)\s*\)/g;
    calculatedExpression = calculatedExpression.replace(sumRegex, (match, content) => {
        let sumValue = 0;

        // Split by commas or semicolons, handling potential whitespace around delimiters
        const parts = content.split(/[,;]/).map(p => p.trim()).filter(p => p);

        for (const part of parts) {
            if (part.includes(':')) {
                // Handle ranges (A1:A3 assumed to be vertical for simplicity, matching test case pattern)
                const [startAddr, endAddr] = part.split(':').map(s => s.trim().toUpperCase());

                let colChar = startAddr[0]; // Assuming single column based on test setup
                let startRow = parseInt(startAddr.substring(1));
                let endRow = parseInt(endAddr.substring(1));

                if (!isNaN(startRow) && !isNaN(endRow) && colChar) {
                    for (let r = Math.min(startRow, endRow); r <= Math.max(startRow, endRow); r++) {
                        const address = `${colChar}${r}`;
                        sumValue += parseFloat(estado.cells[address] || 0);
                    }
                } else {
                    // Fallback if coordinate parsing fails badly
                    console.warn(`Could not process range ${part}.`);
                }

            } else {
                // Handle individual cell reference (A1)
                const address = part.toUpperCase();
                sumValue += parseFloat(estado.cells[address] || 0);
            }
        }
        return sumValue.toString();
    });


    // --- 2. Evaluación de expresiones aritméticas simples ---
    let tempExpression = calculatedExpression;

    // Regex para encontrar referencias a celdas (ej: A1, B4)
    const cellRefRegex = /([A-Z]+[0-9]+)/gi; 
    tempExpression = tempExpression.replace(cellRefRegex, (match) => {
        const value = estado.cells[match];
        // Reemplaza la referencia de celda con su valor numérico actual o 0 si no existe.
        return (value !== undefined && !isNaN(parseFloat(value))) ? parseFloat(value) : 0;
    });

    try {
        // Evalúa la expresión matemática resultante (ej: "2+3" o "9")
        if (typeof eval === 'function') {
            const result = eval(tempExpression);
            return String(result);
        } else {
            console.error("Evaluation failed: eval function not available.");
            return formula; 
        }
    } catch (e) {
        // Si la evaluación falla, retornamos la fórmula original para que el usuario vea qué escribió.
        console.warn("Failed to evaluate formula:", e);
        return formula; 
    }
}

/**
 * Selecciona una fila específica en el DOM y actualiza el estado de selección.
 * @param {Event} event - Evento de click.
 */
function selectRow(event) {
    const rowElement = event.currentTarget.closest('tr');
    if (!rowElement) return;

    // 1. Deseleccionar cualquier fila actualmente seleccionada
    document.querySelectorAll('#spreadsheet-container tr').forEach(tr => {
        tr.classList.remove('selected-row');
    });

    // 2. Seleccionar la nueva fila y actualizar estado visual/lógico
    rowElement.classList.add('selected-row');

    // Obtener el número de la fila (contenido del primer TH)
    const rowNumberCell = rowElement.querySelector('th:first-child');
    if (!rowNumberCell) return;

    // Intentar parsear el número, si falla o es inválido, no se selecciona nada.
    const rowNumberMatch = rowNumberCell.textContent.trim();
    if (!isNaN(parseInt(rowNumberMatch))) {
        estado.selectedRow = parseInt(rowNumberMatch);
        console.log(`Fila ${estado.selectedRow} seleccionada.`);
    } else {
        estado.selectedRow = null;
        console.warn("No se pudo determinar el número de fila.");
    }

    // 3. Actualizar la visibilidad y estado de los controles
    updateControlsState();
}


/**
 * Vacía el contenido de todas las celdas en la fila seleccionada del estado y del DOM.
 */
function clearSelectedRow() {
    if (estado.selectedRow === null) return;

    // Usamos un selector que busque la fila activa por su clase o atributo temporalmente añadido
    const selectedRowElement = document.getElementById('spreadsheet-container').querySelector('.selected-row');

    if (!selectedRowElement) {
        console.error("Fila seleccionada no encontrada en el DOM.");
        return;
    }

    // 1. Recorrer todas las celdas de la fila y vaciar su contenido en el estado.
    const cellsInRow = selectedRowElement.querySelectorAll('td');
    cellsInRow.forEach(cell => {
        const address = cell.getAttribute('data-cell');
        if (address) {
            updateCellValue(address, '');
        }
    });

    // 2. Actualizar el DOM y el estado visual.
    render();
    guardar();
    console.log(`Fila ${estado.selectedRow} vaciada.`);
}


/**
 * Marca la fila seleccionada con un color de fondo específico (ya manejado por CSS/DOM).
 */
function colorizeSelectedRow() {
    if (estado.selectedRow === null) return;

    // La selección visual ya ocurre en selectRow, esta función solo confirma el estado lógico y quizás dispara un evento si fuera necesario.
    console.log(`Fila ${estado.selectedRow} marcada con color.`);
    // No se requiere cambio de estado o renderización adicional más allá del selector CSS aplicado en selectRow/updateControlsState.
}


/**
 * Elimina completamente la fila seleccionada del DOM y elimina sus datos del estado.
 */
function deleteSelectedRow() {
    if (estado.selectedRow === null) return;

    // Usamos el selector de clase para asegurar que apuntemos a la fila correcta
    const selectedRowElement = document.getElementById('spreadsheet-container').querySelector('.selected-row');

    if (!selectedRowElement) {
        console.error("No se pudo encontrar la fila a borrar.");
        return;
    }

    // 1. Recopilar las direcciones de todas las celdas en esta fila para eliminarlas del estado.
    const cellsToDelete = selectedRowElement.querySelectorAll('td');
    cellsToDelete.forEach(cell => {
        const address = cell.getAttribute('data-cell');
        if (address) {
            delete estado.cells[address];
        }
    });

    // 2. Eliminar el elemento de la fila del DOM.
    selectedRowElement.remove();

    // 3. Resetear estado y guardar.
    estado.selectedRow = null;
    updateControlsState();
    render(); 
    guardar();
    console.log(`Fila ${estado.selectedRow} eliminada.`);
}


/**
 * Actualiza la habilitación/deshabilitación de los botones de control basados en si hay una fila seleccionada.
 */
function updateControlsState() {
    const isRowSelected = estado.selectedRow !== null;

    // Habilitar/deshabilitar los botones de acción
    document.getElementById('clear-row-btn').disabled = !isRowSelected;
    document.getElementById('colorize-row-btn').disabled = !isRowSelected;
    document.getElementById('delete-row-btn').disabled = !isRowSelected;

    // Si la fila ya está seleccionada, forzar el estado visual de selección (importante si se carga el estado)
    if (isRowSelected) {
        const selectedRowElement = document.getElementById('spreadsheet-container').querySelector('.selected-row');
        if (!selectedRowElement) {
            // Si no hay clase, la agregamos forzando el estilo en JS para que funcione si se carga un estado antiguo
            const rowNumberCell = document.getElementById('spreadsheet-container').querySelector(`th:contains(${estado.selectedRow})`);
            if (rowNumberCell && !document.getElementById('spreadsheet-container').querySelector('.selected-row')) {
                 // Esto es complicado de hacer sin romper el render, pero intentamos forzar la clase en el elemento padre TR
                const rowContainer = rowNumberCell.closest('tr');
                if(rowContainer) rowContainer.classList.add('selected-row');
            }
        }
    } else {
         // Asegurar que si no hay selección, se quita la clase de todos los elementos
        document.querySelectorAll('#spreadsheet-container tr').forEach(tr => {
             tr.classList.remove('selected-row');
        });
    }
}

// ===== DIBUJO: render() arma la pantalla entera desde `estado`. Lo que se muestra se calcula acá; la página no guarda datos. =====
function render() {
  // Selecciona todas las celdas de datos (<td>) dentro del cuerpo de la tabla.
  const cells = document.querySelectorAll('#spreadsheet-container tbody td');

  cells.forEach(cell => {
    // 1. Obtener el identificador de la celda desde los atributos data-*
    const address = cell.getAttribute('data-cell');

    if (address) {
      // 2. Recuperar el valor actual del estado, o usar una cadena vacía por defecto.
      let content = estado.cells[address] || '';

      // 3. Lógica de cálculo: Si es una fórmula, calcular su valor antes de mostrarlo.
      if (content.startsWith('=')) {
          const calculatedValue = evaluateFormula(content);
          content = calculatedValue; // Usamos el resultado calculado para el renderizado
      }

      // 4. Actualizar el contenido visible de la celda en el DOM.
      cell.textContent = content;
    }
  });

  // Después de renderizar, asegurar que los controles se actualicen con el estado seleccionado.
  updateControlsState();
}

// ===== CONTROLES: conectar() se llama UNA sola vez. Cada evento: llama a la LÓGICA, después guardar() y render(). =====
function conectar() {
  const container = document.getElementById('spreadsheet-container');

  /** 
   * Usamos event delegation en el contenedor para capturar eventos de entrada (typing) 
   * en cualquier celda editable dentro de la tabla sin necesidad de añadir un listener a cada elemento.
   */
  container.addEventListener('input', (event) => {
    const target = event.target;

    // Verificar que el objetivo del evento sea una celda de datos y tenga su atributo data-cell.
    if (!target || !target.hasAttribute('data-cell')) return;

    const address = target.getAttribute('data-cell');
    // El nuevo valor es el contenido actual del elemento DOM después del evento 'input'.
    const newValue = target.textContent; 

    // 1. Lógica: Actualizar el estado interno con el nuevo valor.
    updateCellValue(address, newValue); 

    // 2. Persistencia: Guardar el nuevo estado en LocalStorage.
    guardar();

    // 3. Dibujo: Re-renderizar toda la hoja para asegurar que cualquier cambio de formato o cálculo se aplique (aunque aquí solo es texto).
    render();
  });

/** 
 * Event delegation para manejar clics en todas las celdas, especialmente los números de fila.
 */
container.addEventListener('click', (event) => {
    const target = event.target;

    // Detectar si se hizo clic en la celda del número de la fila (el primer <th> de cada tr).
    if (target.tagName === 'TH' && target.parentElement.closest('tbody')) {
        selectRow(event);
    }
});


// ===== ARRANQUE (lo pone el harness: no lo cambies) =====
function arrancar() { cargar(); conectar(); render(); }
if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", arrancar); else arrancar();
