function clearSelectedRow() {
    const rowIndex = estado.selectedRowIndex;
    if (rowIndex === null || rowIndex < 1) {
        alert("Por favor, selecciona una fila primero.");
        return;
    }

    // Obtener todas las celdas de la fila seleccionada
    const rowElement = document.querySelector(`.row-header[data-row-index="${rowIndex}"]`).closest('tr');
    if (!rowElement) {
        console.error("No se pudo encontrar el elemento de la fila.");
        return;
    }

    let cellsClearedCount = 0;

    // Iterar sobre todas las celdas (<th> y <td>) en esa fila
    const allCellsInRow = rowElement.querySelectorAll('th, td');

    allCellsInRow.forEach(cell => {
        const address = cell.getAttribute('data-cell') || `${getColLetter(cell)} ${rowIndex}`;
        // Limpiar el estado y la celda DOM por separado
        updateCellValue(address, '');
        cell.textContent = '';
        cellsClearedCount++;
    });

    guardar();
    render();
}
