### FUNCION: deleteSelectedRow
```js
function deleteSelectedRow() {
    const rowIndex = estado.selectedRowIndex;
    if (rowIndex === null || rowIndex < 1) {
        alert("Por favor, selecciona una fila primero.");
        return;
    }

    if (!confirm(`¿Estás seguro de que deseas eliminar permanentemente la Fila ${rowIndex}?`)) {
        return;
    }

    // 1. Eliminar el elemento de la fila del DOM
    const rowElement = document.querySelector(`.row-header[data-row-index="${rowIndex}"]`).closest('tr');
    if (rowElement) {
        rowElement.remove();
    }

    // 2. Limpiar el estado y los cálculos asociados a esta fila
    let addressesToDelete = [];
    const allCellsInRow = document.querySelectorAll(`#spreadsheet-container tbody tr[data-row-index="${rowIndex}"] th, #spreadsheet-container tbody tr[data-row-index="${rowIndex}"] td`);

    if (allCellsInRow.length) {
        // Recopilar todas las direcciones para eliminarlas del estado
        allCellsInRow.forEach(cell => {
            const address = cell.getAttribute('data-cell');
            if (address) addressesToDelete.push(address);
        });

        addressesToDelete.forEach(address => delete estado.cells[address]);
    }

    // 3. Actualizar el estado de selección y guardar/renderizar
    estado.selectedRowIndex = null;
    guardar();
    render();
}
