### FUNCION: selectRow
```js
/**
 * Selecciona una fila completa (el <tr> que contiene el número de fila) y marca su estado en el DOM.
 * @param {HTMLElement} rowHeader - El elemento <th> del número de la fila clickeado.
 */
function selectRow(rowHeader) {
    // Deseleccionar cualquier otra fila primero
    document.querySelectorAll('#spreadsheet-container tbody th.selected, #spreadsheet-container tbody td.selected').forEach(el => {
        el.classList.remove('selected');
    });

    const row = rowHeader.closest('tr');
    if (row) {
        // Seleccionar el encabezado de la fila y todas las celdas de datos.
        row.querySelectorAll('th, td').forEach(cell => {
            cell.classList.add('selected');
        });
        console.log("Fila seleccionada:", row);
    }
}
