/**
 * Elimina completamente la fila seleccionada del DOM y del estado interno (estado.cells).
 */
function deleteSelectedRow() {
    const selectedCells = document.querySelectorAll('#spreadsheet-container tbody th.selected, #spreadsheet-container tbody td.selected');

    if (selectedCells.length === 0) {
        alert("Por favor, selecciona una fila primero.");
        return;
    }

    if (!confirm("¿Estás seguro de que deseas eliminar esta fila completa? Esta acción es irreversible.")) {
        return;
    }

    const row = selectedCells[0].closest('tr');

    // 1. Limpiar el estado (estado.cells) para todas las celdas de la fila eliminada
    selectedCells.forEach(cell => {
        const address = cell.getAttribute('data-cell') || '';
        delete estado.cells[address];
    });

    // 2. Eliminar la fila del DOM
    row.remove();

    // 3. Persistencia y Dibujo
    guardar();
    render(); // Re-renderizar para asegurar que el resto de la hoja se vea bien.
}
