 */
function deleteSelectedRow() {
    const selectedCells = document.querySelectorAll('#spreadsheet-container tbody th.selected, #spreadsheet-container tbody td.selected');

    if (selectedCells.length === 0) {
        alert("Por favor, selecciona una fila primero.");
        return;
    }

    if (!confirm("¿Estás seguro de que deseas eliminar esta fila completa? Esta acción es irreversible.")) {
