            cell.style.backgroundColor = ''; // Limpiar fondo visual
        });
    });

    // Verificar si el índice es válido (índices de array son 0-based)
    const targetRowIndex = rowIndex - 1; 

    if (targetRowIndex >= 0 && targetRowIndex < rows.length) {
        const selectedRow = rows[targetRowIndex];

        // Aplicar clase visual a la fila completa
        selectedRow.classList.add('selected-row');

        // Reestablecer el estado de selección global (si existiera, lo manejaremos en el DOM)
