/**
 * Maneja el menú contextual (botón derecho) sobre una fila seleccionada.
 * @param {MouseEvent} event - El evento de ratón.
 */
function handleRowContextMenu(event) {
    // Prevenir el menú contextual nativo del navegador
    event.preventDefault();

    const target = event.target;

    // Solo procesar si la selección fue hecha en un área que corresponde a una fila (header o celda)
    if (!estado.selectedRow) return;

    let contextMenuHtml = `
        <div class="context-menu">
            <button data-action="clear" class="action-button">🗑️ Borrar Contenido</button>
            <hr>
            <!-- Aquí se debería añadir un selector de color, pero por simplicidad, simulamos la acción -->
            <button data-action="color:#ff0000" class="action-button">🎨 Cambiar Fondo (Rojo)</button>
        </div>
    `;

    // Crear y mostrar el menú en la posición del clic
    const menu = document.createElement('div');
    menu.className = 'context-menu';
    menu.innerHTML = contextMenuHtml;
    document.body.appendChild(menu);

    // Posicionar el menú de forma visible (usando coordenadas relativas al body)
    menu.style.position = 'absolute';
    menu.style.left = `${event.clientX}px`;
    menu.style.top = `${event.clientY}px`;

    // Añadir listener para manejar la selección del menú
    const menuHandler = (e) => {
        if (!e.target.dataset.action || e.target.tagName !== 'BUTTON') return;

        const action = e.target.dataset.action;

        if (action === 'clear') {
            clearSelectedRowContent();
        } else if (action.startsWith('color:')) {
            const color = action.split(':')[1];
            changeSelectedRowColor(color);
        }

        // Eliminar el menú después de la acción
        menu.removeEventListener('click', menuHandler);
        document.body.removeChild(menu);
    };

    menu.addEventListener('click', menuHandler);
}
