    // El nuevo valor es el contenido actual del elemento DOM después del evento 'input'.
    let newValue = target.textContent; 

    // Si el usuario presiona Delete/Backspace, textContent puede ser vacío o contener texto parcial.
    if (event.inputType === 'deleteContentBackward' || event.inputType === 'deleteContentForward') {
        newValue = '';
    }


    // 1. Lógica: Actualizar el estado interno con el nuevo valor.
    updateCellValue(address, newValue); 

    // 2. Persistencia: Guardar el nuevo estado en LocalStorage.
    guardar();

    // 3. Dibujo: Re-renderizar toda la hoja para asegurar que cualquier cambio de formato o cálculo se aplique (aunque aquí solo es texto).
    render();
  });

  /**
   * Listener para manejar el borrado completo de una fila seleccionada al presionar Delete.
   */
  container.addEventListener('keydown', (event) => {
    // Si se ha seleccionado una fila y se pulsa la tecla Suprimir/Delete
    if (event.key === 'Delete' && selectedRow > 0) {
      event.preventDefault();

      const rowIndex = selectedRow;

      // 1. Borrar contenido de todas las celdas en el estado para esta fila.
      for (let i = 0; i < Object.keys(estado[rowIndex]).length; i++) {
        const columnKey = Object.keys(estado[rowIndex])[i];
        estado[rowIndex][columnKey] = "";
      }

      // 2. Guardar el estado vacío.
      guardar();

      // 3. Renderizar la hoja para reflejar las celdas vacías.
      render();
    }
  });
}
