```js
function conectar() {
  const container = document.getElementById('spreadsheet-container');

  /** 
   * Maneja eventos de entrada (typing) y también keydown para acciones como borrar fila entera.
   */
  container.addEventListener('input', (event) => {
    const target = event.target;

    // Lógica de manejo de tipeo normal: Input
    if (!target || !target.hasAttribute('data-cell')) return;

    const address = target.getAttribute('data-cell');
    const newValue = target.textContent; 

    updateCellValue(address, newValue); 
    guardar();
    render();
  });


  /**
   * Maneja pulsación de teclas para acciones como borrar contenido completo de la fila seleccionada (Delete/Backspace).
   */
  container.addEventListener('keydown', (event) => {
      // Detecta la tecla Supr (Delete key: keyCode 46 o 'Delete')
      if (event.key === 'Delete' || event.keyCode === 46) {
          const target = event.target;

          // Solo procesar si estamos en una celda de datos y no es el evento por defecto del navegador.
          if (!target || !target.hasAttribute('data-cell')) return;

          event.preventDefault(); // Prevenir la acción predeterminada (ej: borrar un carácter)

          const address = target.getAttribute('data-cell');

          // Aquí asumimos que el contexto de 'borrar fila' implica limpiar todas las celdas de esa fila.
          // Dado que no tenemos acceso al estado de selección global, y solo podemos modificar lo visible:
          // Forzamos la limpieza del contenido de la celda enfocada Y llamamos a una función genérica 
          // (que debe existir en el contexto del test harness) para limpiar el resto de la fila.

          updateCellValue(address, ''); // Limpia la celda actual
          render(); // Muestra el cambio inmediatamente

          // *** FIX: Implementar lógica de borrado de fila completa ***
          // Si el entorno sabe qué direcciones pertenecen a esta fila (ej: usando data-row), 
          // debe iterar sobre ellas y vaciar el estado. Asumiendo que la dirección A3 implica la fila 3, 
          // necesitamos borrar todas las celdas de esa fila.

          const rowNumber = parseInt(address.substring(1)); // Obtener número de fila (ej: 3)
          if (!isNaN(rowNumber)) {
              let cellsToClear = [];
              // Esto es una aproximación basada en la estructura A, B, C...
              for (let i = 0; i < 26; i++) { // Asumimos hasta columna Z por seguridad
                  const colChar = String.fromCharCode('A'.charCodeAt(0) + i);
                  const addressToClear = `${colChar}${rowNumber}`;
                  // Solo limpiamos si realmente existen estas celdas en el estado
                  if (estado.cells.hasOwnProperty(addressToClear)) {
                      updateCellValue(addressToClear, '');
                      cellsToClear.push(addressToClear);
                  }
              }
          }

          guardar();
          render(); // Re-renderizar todo después de borrar múltiples celdas
      }
  });
}
