function hideColumn(colLetter) {
    const colIndex = getColIndexFromLetter(colLetter);
    if (colIndex === -1) return;

    // 1. Ocultar el encabezado de la columna
    document.querySelector(`.col-header[data-col-letter="${colLetter}"]`).classList.add('hidden');

    // 2. Iterar sobre todas las filas y ocultar la celda correspondiente en esa posición (índice)
    const rows = document.getElementById('sheet-body').querySelectorAll('.data-row');
    rows.forEach(row => {
        // La columna es el índice + 1, porque 'corner' ocupa el índice 0
        const cellIndex = colIndex + 1; 
        const cellToHide = row.children[cellIndex];
        if (cellToHide) {
            cellToHide.classList.add('hidden');
        }
    });

    // Nota: Si se implementara el ocultamiento de columnas en la primera fila de encabezados, se haría aquí también.
}
