### FUNCION: getColIndexFromLetter
```js
/** 
 * Helper function to get the zero-based column index from a letter (A=0, B=1, etc.)
 * @param {string} colLetter - The column letter.
 * @returns {number} The index or -1 if not found.
 */
function getColIndexFromLetter(colLetter) {
    const match = colLetter.toUpperCase().match(/^[A-Z]$/);
    if (!match) return -1;
    const charCode = match[0].charCodeAt(0);
    // A=65 -> 0, B=66 -> 1, etc. (charCode - 'A'.charCodeAt(0))
    return charCode - 65; 
}
