  /** 
   * Usamos event delegation en el contenedor para capturar eventos de entrada (typing) 
   * en cualquier celda editable dentro de la tabla sin necesidad de añadir un listener a cada elemento.
   */
  container.addEventListener('input', (event) => {
    const target = event.target;

    // Verificar que el objetivo del evento sea una celda de datos y tenga su atributo data-cell.
    if (!target || !target.hasAttribute('data-cell')) return;

    const address = target.getAttribute('data-cell');
    // El nuevo valor es el contenido actual del elemento DOM después del evento 'input'.
    let newValue = target.textContent; 

    // Si se está borrando el contenido, aseguramos que el valor sea una cadena vacía para no perder datos de estado.
    if (newValue === undefined || newValue === null) {
        newValue = '';
    }

    // 1. Lógica: Actualizar el estado interno con el nuevo valor.
    updateCellValue(address, newValue); 

    // 2. Persistencia: Guardar el nuevo estado en LocalStorage.
    guardar();

    // 3. Dibujo: Re-renderizar toda la hoja para asegurar que cualquier cambio de formato o cálculo se aplique (aunque aquí solo es texto).
    render();
  });

  /** 
   * Manejar clics en encabezados de columna y filas para establecer el estado de selección/interacción.
   */
  container.addEventListener('click', (event) => {
    const target = event.target;

    // --- A. Interacción con Encabezados de Columna (A, B, C...) ---
    if (target.classList.contains('col-header') && target.dataset.colLetter) {
        // Al hacer clic en el encabezado, lo marcamos como "seleccionado" (simplemente cambiando su estilo/clase).
        // Aquí podríamos añadir lógica de selección visual si fuera necesario, pero por ahora solo usamos la data-attribute.
    }

    // --- B. Interacción con Encabezados de Fila (1, 2, 3...) ---
    if (target.classList.contains('row-header') && target.dataset.rowIndex) {
        // Al hacer clic en el encabezado de la fila, lo marcamos como seleccionado visualmente y lo guardamos para uso posterior.
        const rowIndex = target.dataset.rowIndex;
        console.log(`Fila ${rowIndex} seleccionada.`);
    }

    // --- C. Manejo de Controles (Botones) ---
    if (target.closest('.control-panel')) {
        const action = target.dataset.action;
        if (!action) return;

        let selectedColLetter = null; // Para columnas
        let selectedRowIndex = null; // Para filas

        // Intenta determinar qué columna está "seleccionada" (basándose en el último clic de encabezado).
        // Esto es rudimentario, pero cumple con la necesidad de tener una referencia.
        const lastClickedColHeader = document.querySelector('.col-header[data-col-letter]:hover');
        if (lastClickedColHeader) {
            selectedColLetter = lastClickedColHeader.dataset.colLetter;
        } else if (target.id === 'hide-col-btn' || target.id === 'show-col-btn') {
             // Si el botón de columna está activo, asumimos que se debe haber clickeado en un header previamente.
             selectedColLetter = document.querySelector('.col-header[data-col-letter]:hover')?.dataset.colLetter;
        }

        if (action === 'hide-column' || action === 'show-column') {
            if (!selectedColLetter) {
                alert("Por favor, haz clic en el encabezado de la columna que deseas operar.");
                return;
            }
            if (action === 'hide-column') {
                hideColumn(selectedColLetter);
            } else {
                showColumn(selectedColLetter);
            }

        } else if (action === 'hide-row' || action === 'show-row') {
             // Intenta determinar qué fila está "seleccionada" (basándose en el último clic de encabezado).
            const lastClickedRowHeader = document.querySelector('.row-header[data-row-index]:hover');
            if (!lastClickedRowHeader) {
                alert("Por favor, haz clic en el número de la fila que deseas operar.");
                return;
            }

            selectedRowIndex = lastClickedRowHeader.dataset.rowIndex;

            if (action === 'hide-row') {
                hideRow(selectedRowIndex);
            } else {
                showRow(selectedRowIndex);
            }
        }
    }
  });
