                if (target.classList.contains('show-col')) {
                    showColumn(colLetter);
                } else if (target.classList.contains('hide-col')) {
                    hideColumn(colLetter);
                }
            }

        // 2. Manejar el clic en la cabecera de fila (Row Header Click)
        } else if (target.closest('.row-header') && target.hasAttribute('data-row-number')) {
            const rowNumber = target.getAttribute('data-row-number');

             if (event.isTrusted) { 
                event.preventDefault();

                // Lógica para mostrar/ocultar fila:
                if (target.classList.contains('show-row')) {
                    showRow(rowNumber);
                } else if (target.classList.contains('hide-row')) {
                    hideRow(rowNumber);
                }
            }
        }

    });

    /* --- Manejo de Eventos Globales para Mostrar/Ocultar Todo --- */
    document.getElementById('show-all-rows')?.addEventListener('click', () => {
        // Muestra todas las filas en el tbody
        document.querySelectorAll('#spreadsheet-container tbody tr').forEach(row => {
            row.style.display = '';
        });
    });

    document.getElementById('show-all-cols')?.addEventListener('click', () => {
        // Muestra todas las columnas de datos (td) y sus encabezados
        const allCols = document.querySelectorAll('.header-cell[data-col-letter]');
        allCols.forEach(header => header.style.display = '');

        document.querySelectorAll('#spreadsheet-container tbody td').forEach(cell => {
            cell.style.display = '';
        });
    });
