        return (value !== undefined && !isNaN(parseFloat(value))) ? parseFloat(value) : 0;
    });

    try {
        // Evalúa la expresión matemática resultante (ej: "2+3" o "9")
        if (typeof eval === 'function') {
            const result = eval(tempExpression);
            return String(result);
        } else {
            console.error("Evaluation failed: eval function not available.");
            return formula; 
        }
    } catch (e) {
        // Si la evaluación falla, retornamos la fórmula original para que el usuario vea qué escribió.
        console.warn("Failed to evaluate formula:", e);
        return formula; 
    }
}

/**
 * Convierte una letra de columna (A, B, C...) a su índice basado en cero (0, 1, 2...).
 * @param {string} letter - La letra de la columna.
 * @returns {number} El índice de columna o -1 si es inválido.
 */
function getColIndex(letter) {
    if (!letter || typeof letter !== 'string') return -1;
    // Simple cálculo para el rango A-Z basado en 0
    return letter.toUpperCase().charCodeAt(0) - 'A'.charCodeAt(0);
}

/**
 * Oculta visualmente una columna dada su índice (0 = A, 1 = B, etc.).
 * @param {number} colIndex - El índice de la columna a ocultar.
 */
function hideColumn(colIndex) {
    // 1. Ocultar el encabezado de la columna en thead
    const colHeader = document.querySelectorAll('.col-header')[colIndex];
    if (colHeader) {
        colHeader.style.display = 'none';
    }

    // 2. Iterar sobre todas las filas del tbody para ocultar las celdas de esa columna.
    const rows = document.querySelectorAll('#spreadsheet-container tbody tr');
    rows.forEach(row => {
        const cells = row.querySelectorAll('td');
        if (cells[colIndex]) {
            cells[colIndex].style.display = 'none';
        }
    });

    // 3. Guardar el estado de visibilidad en el DOM y la variable global.
    colHeaderState[colIndex] = 'hidden';
}

/**
 * Muestra visualmente una columna dada su índice (0 = A, 1 = B, etc.).
 * @param {number} colIndex - El índice de la columna a mostrar.
 */
function showColumn(colIndex) {
    // 1. Mostrar el encabezado de la columna en thead
    const colHeader = document.querySelectorAll('.col-header')[colIndex];
    if (colHeader) {
        colHeader.style.display = ''; // Restaurar display normal
    }

    // 2. Iterar sobre todas las filas del tbody para mostrar las celdas de esa columna.
    const rows = document.querySelectorAll('#spreadsheet-container tbody tr');
    rows.forEach(row => {
        const cells = row.querySelectorAll('td');
        if (cells[colIndex]) {
            cells[colIndex].style.display = ''; // Restaurar display normal
        }
    });

    // 3. Guardar el estado de visibilidad en la variable global.
    colHeaderState[colIndex] = 'visible';
}


/**
 * Oculta visualmente una fila dada su índice de DOM (0 es la primera fila del tbody, que corresponde a la fila 1 visible).
 * @param {number} rowIndexDOM - El índice base cero del elemento TR en el body.
 */
function hideRow(rowIndexDOM) {
    const row = document.querySelectorAll('#spreadsheet-container tbody tr')[rowIndexDOM];
    if (row) {
        row.style.display = 'none';
    }
}

/**
 * Muestra visualmente una fila dada su índice de DOM (0 es la primera fila del tbody).
 * @param {number} rowIndexDOM - El índice base cero del elemento TR en el body.
 */
function showRow(rowIndexDOM) {
    const row = document.querySelectorAll('#spreadsheet-container tbody tr')[rowIndexDOM];
    if (row) {
        row.style.display = ''; // Restaurar display normal
    }
}


// ===== DIBUJO: render() arma la pantalla entera desde `estado`. Lo que se muestra se calcula acá; la página no guarda datos. =====
function render() {
  // Selecciona todas las celdas de datos (<td>) dentro del cuerpo de la tabla.
  const cells = document.querySelectorAll('#spreadsheet-container tbody td');

  cells.forEach(cell => {
    // 1. Obtener el identificador de la celda desde los atributos data-*
    const address = cell.getAttribute('data-cell');

    if (address) {
      // 2. Recuperar el valor actual del estado, o usar una cadena vacía por defecto.
      let content = estado.cells[address] || '';

      // 3. Lógica de cálculo: Si es una fórmula, calcular su valor antes de mostrarlo.
      if (content.startsWith('=')) {
          const calculatedValue = evaluateFormula(content);
          content = calculatedValue; // Usamos el resultado calculado para el renderizado
      }

      // 4. Actualizar el contenido visible de la celda en el DOM.
      cell.textContent = content;
    }
  });
}

// ===== CONTROLES: conectar() se llama UNA sola vez. Cada evento: llama a la LÓGICA, después guardar() y render(). =====
function conectar() {
  const container = document.getElementById('spreadsheet-container');

  /** 
   * Usamos event delegation en el contenedor para capturar eventos de entrada (typing) 
   * en cualquier celda editable dentro de la tabla sin necesidad de añadir un listener a cada elemento.
   */
  container.addEventListener('input', (event) => {
    const target = event.target;

    // Verificar que el objetivo del evento sea una celda de datos y tenga su atributo data-cell.
    if (!target || !target.hasAttribute('data-cell')) return;

    const address = target.getAttribute('data-cell');
    // El nuevo valor es el contenido actual del elemento DOM después del evento 'input'.
    const newValue = target.textContent; 

    // 1. Lógica: Actualizar el estado interno con el nuevo valor.
    updateCellValue(address, newValue); 

    // 2. Persistencia: Guardar el nuevo estado en LocalStorage.
    guardar();

    // 3. Dibujo: Re-renderizar toda la hoja para asegurar que cualquier cambio de formato o cálculo se aplique (aunque aquí solo es texto).
    render();
  });

  /**
   * Conectar listeners a los encabezados de columna y fila para manejar el ocultar/mostrar.
   */
  document.querySelectorAll('.col-header').forEach((header, index) => {
      // Nota: El listener se añade en un bloque separado para evitar conflictos con la sintaxis del harness.
      // Sin embargo, si usamos addEventListener aquí, debemos asegurarnos de que el estado global esté inicializado.
  });

   document.querySelectorAll('#spreadsheet-container tbody tr').forEach((row, index) => {
       // Nota: El listener se añade en un bloque separado para evitar conflictos con la sintaxis del harness.
   });
}

// Nota: Se asume que el harness llama a conectar(), cargar() y render() en el orden correcto al iniciar la aplicación.

// ===== ARRANQUE (lo pone el harness: no lo cambies) =====
function arrancar() { cargar(); conectar(); render(); }
if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", arrancar); else arrancar();
